import{_ as r,C as n,o as t,c as o,a7 as a,b as h,w as i,a as l,E as d,a8 as E}from"./chunks/framework.BCbKzsgW.js";const C=JSON.parse('{"title":"Token、JWT 与刷新撤销","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/token-jwt.md","filePath":"development/common/authentication/token-jwt.md","lastUpdated":1793703140000}'),p={name:"development/common/authentication/token-jwt.md"};function k(c,e,A,u,f,B){const s=n("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a(`<h1 id="tokenjwt-yu-shua-xin-che-xiao" tabindex="-1">Token、JWT 与刷新撤销 <a class="header-anchor" href="#tokenjwt-yu-shua-xin-che-xiao" aria-label="Permalink to &quot;Token、JWT 与刷新撤销&quot;">​</a></h1><p>Token 是凭据或授权结果的载体，不规定其内部格式。随机字符串可以引用服务端记录，JWT 则携带结构化声明；选择格式之前，需要先确定谁签发、谁接受、可以访问什么，以及何时停止接受。</p><h2 id="qu-fen-ling-pai-yong-tu-yu-ge-shi" tabindex="-1">区分令牌用途与格式 <a class="header-anchor" href="#qu-fen-ling-pai-yong-tu-yu-ge-shi" aria-label="Permalink to &quot;区分令牌用途与格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>令牌</th><th>接收方与用途</th><th>主要边界</th></tr></thead><tbody><tr><td>Access Token</td><td>资源服务器，访问指定 API</td><td>受众、权限范围、有效期</td></tr><tr><td>Refresh Token</td><td>授权服务器，申请新令牌</td><td>客户端、授权范围、刷新链与撤销</td></tr><tr><td>ID Token</td><td>OIDC 客户端，确认认证结果</td><td>客户端受众、认证事务与身份</td></tr><tr><td>恢复令牌</td><td>账号恢复入口，完成特定动作</td><td>单次、用途、账号与短有效期</td></tr></tbody></table><p>ID Token 不作为通用 API Access Token，Refresh Token 不发给业务 API。API 不应因为某段字符串可以解码成 JWT，就认为它适用于当前接口。</p><p>随机不透明令牌便于集中检查活动状态，代价是查询。JWT 可由 API 本地验证，代价是负载更大、密钥管理与状态滞后。OAuth introspection 与撤销分别由 <a href="https://www.rfc-editor.org/rfc/rfc7662.html" target="_blank" rel="noreferrer">RFC 7662</a>和 <a href="https://www.rfc-editor.org/rfc/rfc7009.html" target="_blank" rel="noreferrer">RFC 7009</a>定义，令牌是否自包含并不决定它必须采用哪种查询方式。</p><h2 id="jwt-de-qian-ming-yu-sheng-ming" tabindex="-1">JWT 的签名与声明 <a class="header-anchor" href="#jwt-de-qian-ming-yu-sheng-ming" aria-label="Permalink to &quot;JWT 的签名与声明&quot;">​</a></h2><p>常见签名 JWT 使用三个以点号分隔的部分：JOSE Header、Claims、签名或 MAC。Base64url 编码不是加密，普通签名 JWT 的内容可被持有者读取。<a href="https://www.rfc-editor.org/rfc/rfc7519.html" target="_blank" rel="noreferrer">RFC 7519</a>也允许使用 JWE 保护机密性，不能把“JWT”一概等同于三段式明文负载。</p><p>以下仅是 Access Token 的示意声明，不是已签发的可用令牌：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;iss&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://identity.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user_123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;aud&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orders-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;client_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mobile-app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orders:read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;iat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1793318400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1793319000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;jti&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token_7d6f&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>exp</code> 和 <code>iat</code> 使用 Unix 秒数；示例给出 10 分钟有效期，只用于说明时间关系。不要混用毫秒，也不要默认所有声明都由任意 JWT 标准强制要求。应用应选择并固定验证配置；采用 OAuth JWT Access Token profile 时，按 <a href="https://www.rfc-editor.org/rfc/rfc9068.html#section-2.2" target="_blank" rel="noreferrer">RFC 9068</a>处理其必需声明与 <code>typ</code>。</p><h2 id="yan-zheng-shun-xu" tabindex="-1">验证顺序 <a class="header-anchor" href="#yan-zheng-shun-xu" aria-label="Permalink to &quot;验证顺序&quot;">​</a></h2><p>依据 <a href="https://www.rfc-editor.org/rfc/rfc8725.html#section-3" target="_blank" rel="noreferrer">RFC 8725</a>，验证器需要固定可接受算法、密钥来源、签发者、受众和令牌用途，防止算法替换与跨用途混用。</p><p>工程上可按下列边界配置成熟库：</p><ol><li>限制输入长度与结构，不允许无界嵌套或超大声明。</li><li>使用配置的算法集合和签发者对应密钥验证密码学保护。</li><li>校验 <code>iss</code>、<code>aud</code>、<code>exp</code>，并按选定 profile 检查其他必需声明。</li><li>处理 <code>nbf</code>、允许的时钟偏差与令牌类型，拒绝不符合当前用途的令牌。</li><li>将已验证主体交给业务授权，检查账号、成员和对象状态。</li></ol><p>Header 中的 <code>kid</code> 是密钥选择提示，不是信任依据；不根据任意 <code>jku</code>、<code>x5u</code> 或 <code>kid</code> 去访问攻击者指定的 URL、文件或数据库表达式。共享 HMAC 密钥意味着每个验证方也具备签发能力；多个独立 API 场景通常更适合由签发方保管私钥、验证方持有公钥。</p><h2 id="refresh-token-lun-huan" tabindex="-1">Refresh Token 轮换 <a class="header-anchor" href="#refresh-token-lun-huan" aria-label="Permalink to &quot;Refresh Token 轮换&quot;">​</a></h2><p><a href="https://www.rfc-editor.org/rfc/rfc9700.html#section-4.14" target="_blank" rel="noreferrer">RFC 9700 §4.14</a>要求公共客户端的 Refresh Token 使用发送方约束或轮换等规定的保护方式。轮换时每次刷新得到新 Refresh Token，旧值再次出现可作为重放信号。</p><p>建议每台设备或每次授权使用独立刷新族，记录 <code>family_id</code>、令牌摘要、账号、客户端、状态、父子关系和绝对期限。下图是一种事务设计，不是标准指定的表结构；它选择在重用时撤销刷新族。</p>`,19)),(t(),h(E,null,{default:i(()=>[d(s,{id:"mermaid-137",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20A%20as%20%E6%8E%88%E6%9D%83%E6%9C%8D%E5%8A%A1%0A%20%20%20%20participant%20D%20as%20%E5%88%B7%E6%96%B0%E8%AE%B0%E5%BD%95%E5%BA%93%0A%20%20%20%20C-%3E%3EA%3A%20%E6%8F%90%E4%BA%A4%20Refresh%20Token%20R1%0A%20%20%20%20A-%3E%3ED%3A%20BEGIN%EF%BC%8C%E9%94%81%E5%AE%9A%E4%BB%A4%E7%89%8C%E4%B8%8E%E5%88%B7%E6%96%B0%E6%97%8F%0A%20%20%20%20D--%3E%3EA%3A%20R1%20%E7%8A%B6%E6%80%81%E5%8F%8A%E5%88%B7%E6%96%B0%E6%97%8F%E7%8A%B6%E6%80%81%0A%20%20%20%20A-%3E%3EA%3A%20%E6%A3%80%E6%9F%A5%E5%AE%A2%E6%88%B7%E7%AB%AF%E3%80%81%E8%B4%A6%E5%8F%B7%E4%B8%8E%E6%9C%89%E6%95%88%E6%9C%9F%0A%20%20%20%20alt%20%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%EF%BC%8CR1%20%E4%B8%BA%20active%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20R1%20%E6%94%B9%E4%B8%BA%20used%EF%BC%8C%E5%88%9B%E5%BB%BA%E5%94%AF%E4%B8%80%20R2%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20COMMIT%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%96%B0%20Access%20Token%20%E4%B8%8E%20R2%0A%20%20%20%20else%20%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%EF%BC%8C%E4%BD%86%20R1%20%E5%B7%B2%E4%BD%BF%E7%94%A8%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20%E6%92%A4%E9%94%80%E5%88%B7%E6%96%B0%E6%97%8F%EF%BC%8C%E5%86%99%E5%AE%89%E5%85%A8%E4%BA%8B%E4%BB%B6%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20COMMIT%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%8B%92%E7%BB%9D%E5%88%B7%E6%96%B0%EF%BC%8C%E8%A6%81%E6%B1%82%E9%87%8D%E6%96%B0%E7%99%BB%E5%BD%95%0A%20%20%20%20else%20%E5%85%B6%E4%BB%96%E6%A0%A1%E9%AA%8C%E5%A4%B1%E8%B4%A5%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20ROLLBACK%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%8B%92%E7%BB%9D%E5%88%B7%E6%96%B0%0A%20%20%20%20end%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>令牌记录和刷新族的锁定或条件更新需要遵守一致的并发协议，防止刷新与撤销同时创建出可用后继。图中的数据库只保存令牌摘要，R1、R2 的原始值不进入普通日志。</p><p>数据库无法分辨重用一定来自攻击者。两个标签页同时刷新、网络重试或客户端丢失响应，也可能触发同一现象。</p><h2 id="bing-fa-shua-xin-yu-xiang-ying-diu-shi" tabindex="-1">并发刷新与响应丢失 <a class="header-anchor" href="#bing-fa-shua-xin-yu-xiang-ying-diu-shi" aria-label="Permalink to &quot;并发刷新与响应丢失&quot;">​</a></h2><p>客户端应采用单次在途刷新：同一设备同一时刻只有一个刷新请求，其他请求等待结果。浏览器多标签页还需要跨页协调，不能只在每个页面各设一把内存锁。</p><p>如果事务已提交但响应丢失，客户端只持有旧令牌。可选择要求重新登录，或设计严格绑定客户端与幂等请求的短期结果重放机制。后者需要受保护地保留可重发结果，增加秘密存储与泄露面；不能用无限接受旧 Refresh Token 来解决。</p><p>删除所有 <code>used</code> 记录会丢失重用检测证据，应按刷新族有效期与审计需求清理。Refresh Token 原始值也不能写入普通数据库日志、链路追踪或错误上报。</p><h2 id="che-xiao-yu-quan-xian-bian-geng" tabindex="-1">撤销与权限变更 <a class="header-anchor" href="#che-xiao-yu-quan-xian-bian-geng" aria-label="Permalink to &quot;撤销与权限变更&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>生效方式</th><th>代价</th></tr></thead><tbody><tr><td>短期 Access Token</td><td>等待过期</td><td>有明确残余窗口</td></tr><tr><td>在线 introspection</td><td>API 查询当前状态</td><td>可用性、延迟与缓存一致性</td></tr><tr><td>令牌或会话撤销列表</td><td>查询 <code>jti</code> 或登录实例</td><td>存储与查询负担</td></tr><tr><td>账号安全版本</td><td>比较当前版本</td><td>需获得足够新的版本状态</td></tr><tr><td>撤销 Refresh Token</td><td>阻止继续刷新</td><td>已有 Access Token 通常仍需额外处理</td></tr></tbody></table><p>权限变化后，即使旧 Access Token 仍有效，资源服务也可以重新查询成员和对象权限。不能把“签名有效”和“当前业务允许”合并成一个判断。</p><h2 id="mi-yao-lun-huan-yu-xie-lu" tabindex="-1">密钥轮换与泄露 <a class="header-anchor" href="#mi-yao-lun-huan-yu-xie-lu" aria-label="Permalink to &quot;密钥轮换与泄露&quot;">​</a></h2><p>正常轮换先发布新公钥，让验证方有机会获取，再切换签名私钥；保留旧公钥直到旧令牌及允许的时钟偏差窗口结束。验证方对未知 <code>kid</code> 的刷新要限频，防止攻击者触发无界远程请求。</p><p>私钥泄露需要紧急拒绝旧密钥，不能机械等待自然过期。对于不再查询签发方的 API，必须有密钥失效传播与缓存刷新机制。JWKS 拉取失败时可按明确策略使用尚可信的缓存，未知密钥不能降级跳过签名。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc7519.html" target="_blank" rel="noreferrer">RFC 7519 — JSON Web Token</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc8725.html" target="_blank" rel="noreferrer">RFC 8725 — JWT Best Current Practices</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc9068.html" target="_blank" rel="noreferrer">RFC 9068 — JWT Profile for OAuth 2.0 Access Tokens</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc9700.html#section-4.14" target="_blank" rel="noreferrer">RFC 9700 §4.14 — Refresh Token Protection</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc7662.html" target="_blank" rel="noreferrer">RFC 7662 — Token Introspection</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc7009.html" target="_blank" rel="noreferrer">RFC 7009 — Token Revocation</a></li></ul>',14))])}const F=r(p,[["render",k]]);export{C as __pageData,F as default};
